static inline const char *W32kNameFromSsn(unsigned ssn)
{
    unsigned idx = ssn - W32K_NAMES_BASE;
    if (idx < W32K_NAMES_COUNT && W32kSyscallNames[idx][0] != '\0')
        return W32kSyscallNames[idx];
    /* SSN not described in this JSON or out of range */
    static char _buf[20];
    (void)snprintf(_buf, sizeof(_buf), "<w32k:0x%04X>", ssn);
    return _buf;
}

